def canon(cells):
    pts=list(cells); forms=[]
    for k in range(8):
      trans=[]
      for r,c in pts:
        if k<4: x,y=r,c
        else:x,y=r,-c
        for _ in range(k%4): x,y=y,-x
        trans.append((x,y))
      mr=min(x for x,y in trans);mc=min(y for x,y in trans)
      forms.append(tuple(sorted((x-mr,y-mc) for x,y in trans)))
    return min(forms)
C3=comps(3); C5=comps(5)
for i,c in enumerate(C3):
    matches=[(j,len(x),min((r,c) for r,c in x)) for j,x in enumerate(C5) if canon(x)==canon(c)]
    if matches: print('3',i,len(c), min(c), matches)
